// components/pages/TillRegistration.js
import React, { useState } from 'react';
import { apiCall, normalizePhone } from '../../utils/api';

const TillRegistration = ({ showToast }) => {
  const [formData, setFormData] = useState({
    phone: '',
    name: '',
    idNumber: '',
    dob: '',
    tillNumber: '',
    storeNumber: '',
    operatorId: ''
  });
  const [loading, setLoading] = useState(false);
  const [feedback, setFeedback] = useState('');
  const [fetchInfo, setFetchInfo] = useState({ type: '', message: '' });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleFetchLine = async () => {
    const phone = formData.phone.trim();
    if (!phone) {
      setFetchInfo({ type: 'error', message: 'Enter a phone number' });
      return;
    }

    setFetchInfo({ type: 'info', message: 'Searching...' });

    const res = await apiCall('getLines');
    if (!res.success || !res.lines) {
      setFetchInfo({ type: 'error', message: 'Error fetching lines' });
      return;
    }

    const normalizedInput = normalizePhone(phone);
    const found = res.lines.find(line => normalizePhone(line.phone) === normalizedInput);

    if (found) {
      setFormData(prev => ({
        ...prev,
        name: found.name,
        idNumber: found.idNumber,
        dob: found.dob,
        operatorId: generateOperatorId(found.name)
      }));
      setFetchInfo({ type: 'success', message: `Line found: ${found.name}` });
      showToast('Line found! You can now register the till.');
    } else {
      setFetchInfo({ type: 'error', message: `No line found for "${phone}"` });
      showToast('No line found with this phone number', true);
      setFormData(prev => ({
        ...prev,
        name: '',
        idNumber: '',
        dob: '',
        operatorId: ''
      }));
    }
  };

  const generateOperatorId = (name) => {
    const nameParts = name.trim().split(/\s+/);
    if (nameParts.length === 1) {
      return nameParts[0].substring(0, 2).toUpperCase();
    }
    return (nameParts[0].charAt(0) + nameParts[nameParts.length - 1].charAt(0)).toUpperCase();
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const { phone, name, tillNumber, storeNumber } = formData;

    if (!phone || !tillNumber || !storeNumber || !name) {
      setFeedback({ type: 'error', message: 'Please fetch a line first and fill all fields' });
      return;
    }

    setLoading(true);
    setFeedback({ type: 'info', message: 'Registering...' });

    const cleanPhone = phone.replace(/\D/g, '');
    const res = await apiCall('registerTill', { 
      ...formData,
      phone: cleanPhone
    });

    if (res.success) {
      setFeedback({ type: 'success', message: 'Till registered successfully!' });
      setFormData(prev => ({ ...prev, tillNumber: '', storeNumber: '' }));
      showToast('Till registered successfully!');
      setTimeout(() => setFeedback(''), 3000);
    } else {
      setFeedback({ type: 'error', message: res.error });
    }
    setLoading(false);
  };

  return (
    <div className="form-container">
      <h3 className="section-title"><i className="fas fa-cash-register"></i> Register New Till</h3>
      <form className="vertical-form" onSubmit={handleSubmit}>
        <div className="form-group">
          <label><i className="fas fa-phone"></i> Phone Number (Lookup Line)</label>
          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            <input 
              type="tel" 
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              placeholder="0712345678"
              style={{ flex: 1 }}
            />
            <button 
              type="button" 
              className="btn-secondary" 
              onClick={handleFetchLine}
              style={{ width: 'auto', padding: '10px 20px' }}
            >
              <i className="fas fa-search"></i> Fetch Line Data
            </button>
          </div>
          {fetchInfo.message && (
            <div className={`fetch-info ${fetchInfo.type}`}>
              {fetchInfo.message}
            </div>
          )}
        </div>
        <div className="form-group">
          <label><i className="fas fa-user"></i> Full Name</label>
          <input 
            type="text" 
            name="name"
            value={formData.name}
            readOnly
            placeholder="Will auto-fill"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-id-card"></i> ID Number</label>
          <input 
            type="text" 
            name="idNumber"
            value={formData.idNumber}
            readOnly
            placeholder="Will auto-fill"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-calendar"></i> Date of Birth</label>
          <input 
            type="text" 
            name="dob"
            value={formData.dob}
            readOnly
            placeholder="Will auto-fill"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-hashtag"></i> Till Number</label>
          <input 
            type="text" 
            name="tillNumber"
            value={formData.tillNumber}
            onChange={handleChange}
            placeholder="e.g., T001"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-store"></i> Store Number</label>
          <input 
            type="text" 
            name="storeNumber"
            value={formData.storeNumber}
            onChange={handleChange}
            placeholder="e.g., STR01"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-user-tag"></i> Operator ID</label>
          <input 
            type="text" 
            name="operatorId"
            value={formData.operatorId}
            readOnly
            placeholder="Auto-generated"
          />
        </div>
        <button type="submit" className="btn" disabled={loading}>
          <i className="fas fa-save"></i> {loading ? 'Registering...' : 'Register Till'}
        </button>
        {feedback && (
          <div className={`fetch-info ${feedback.type}`} style={{ marginTop: '1rem' }}>
            {feedback.message}
          </div>
        )}
      </form>
    </div>
  );
};

export default TillRegistration;
